SELECT SUM(revenue_inr) AS total_revenue
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG';

SELECT SUM(line_amount) as total_sales_may
FROM store.pos_lines
WHERE bill_ts >= '2026-05-01' AND bill_ts < '2026-06-01';

SELECT SUM(amount_inr) as total_refunds_june
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT sku, gtin, name, flow
FROM store.products
ORDER BY sku;

SELECT sku, name, pack_size
FROM store.products
WHERE name ILIKE '%atta%';

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%atta%';

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%milk%' OR name ILIKE '%toned%';

SELECT sku, gtin, name, pack, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%';

SELECT COUNT(*) AS shipment_count
FROM warehouse.shipments
WHERE arrived_ts >= '2026-05-01' AND arrived_ts < '2026-06-01';

SELECT SUM(pallets) AS total_pallets
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

SELECT COUNT(*) AS grn_lines
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT DISTINCT tender
FROM payments.pos_payments
ORDER BY tender;

SELECT * FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01'
ORDER BY complaint_ts;

SELECT * FROM warehouse.shipments
WHERE slot_start >= '2026-06-10' AND slot_start < '2026-06-11'
ORDER BY slot_start;

SELECT * FROM store.fresh_deliveries
WHERE route = 'R-07' AND delivery_ts >= '2026-06-10' AND delivery_ts < '2026-06-11'
ORDER BY delivery_ts;

SELECT COUNT(DISTINCT pl.bill_id) as total_bills_in_june
FROM store.pos_lines pl
WHERE pl.bill_ts >= '2026-06-01' AND pl.bill_ts < '2026-07-01';
